function calendarWindow(calendarId, now = new Date()) {
  if (
    typeof calendarId !== "string" ||
    !calendarId.trim() ||
    calendarId === "YOUR_GOOGLE_CALENDAR_ID"
  ) {
    throw new Error("Enter the Google Calendar ID.");
  }
  const from = new Date(now);
  const until = new Date(from.getTime() + 12 * 60 * 60 * 1000);
  const query = {
    timeMin: from.toISOString(),
    timeMax: until.toISOString(),
    singleEvents: "true",
    showDeleted: "false",
    fields:
      "nextPageToken,timeZone,items(id,status,transparency,summary,start(dateTime,timeZone),end(dateTime))",
  };
  return { endpoint: "/calendars/" + encodeURIComponent(calendarId.trim()) + "/events", query };
}

const calendarId = "YOUR_GOOGLE_CALENDAR_ID";
return [{ json: calendarWindow(calendarId, $input.first().json.timestamp ?? undefined) }];

function collectCalendarPage(state, status, page) {
  if (
    status !== 200 ||
    !page ||
    typeof page !== "object" ||
    Array.isArray(page) ||
    (page.items !== undefined && !Array.isArray(page.items))
  ) {
    throw new Error("Google Calendar did not return a valid event page.");
  }
  const old = state ?? { events: [], tokens: [], timezone: null };
  const cursor = page.nextPageToken ?? null;
  if (cursor !== null && (typeof cursor !== "string" || !cursor || old.tokens.includes(cursor))) {
    throw new Error("Google Calendar returned an invalid or repeated page token.");
  }
  const tokens = cursor === null ? old.tokens : [...old.tokens, cursor];
  if (cursor && tokens.length >= 100) {
    throw new Error("The Calendar query exceeded 100 pages.");
  }
  return {
    events: [...old.events, ...(page.items ?? [])],
    tokens,
    cursor,
    timezone: old.timezone ?? page.timeZone ?? "UTC",
  };
}

function selectMeetings(window, state) {
  if (!state || state.cursor !== null) throw new Error("Calendar pagination is incomplete.");
  const start = Date.parse(window.query.timeMin);
  const end = Date.parse(window.query.timeMax);
  const seen = new Set();
  const meetings = [];
  for (const event of state.events) {
    if (!event || typeof event !== "object" || Array.isArray(event))
      throw new Error("Invalid Calendar event.");
    const { id, summary, status, transparency } = event;
    if (
      status === "cancelled" ||
      transparency === "transparent" ||
      typeof summary !== "string" ||
      !summary.trim() ||
      /signal|minute meeting|in person/i.test(summary) ||
      !event.start?.dateTime ||
      !event.end?.dateTime
    )
      continue;
    const startMs = Date.parse(event.start.dateTime);
    const endMs = Date.parse(event.end.dateTime);
    if (
      !Number.isFinite(startMs) ||
      !Number.isFinite(endMs) ||
      endMs <= startMs ||
      typeof id !== "string" ||
      !id
    )
      throw new Error("A timed Calendar event has invalid scheduling data.");
    if (startMs < start || startMs >= end || seen.has(id)) continue;
    const topic = "Meeting with " + summary;
    const duration = Math.ceil((endMs - startMs) / 60000);
    if (topic.length > 200 || duration > 1440)
      throw new Error("A Calendar event exceeds the Zoom meeting limits.");
    seen.add(id);
    meetings.push({
      eventId: id,
      topic,
      startTime: new Date(startMs).toISOString().replace(/\.000Z$/, "Z"),
      duration,
      timezone: event.start.timeZone || state.timezone,
    });
  }
  return meetings;
}

let state = null;
for (const { json } of $input.all()) state = collectCalendarPage(state, json.statusCode, json.body);
return selectMeetings($("Choose the calendar and 12-hour window").first().json, state).map(
  (event) => ({ json: event }),
);

function confirmMeeting(event, meeting) {
  if (
    (typeof meeting?.id !== "string" && !Number.isSafeInteger(meeting?.id)) ||
    !/^\d+$/.test(String(meeting.id)) ||
    meeting.topic !== event.topic ||
    Date.parse(meeting.startTime) !== Date.parse(event.startTime) ||
    meeting.duration !== event.duration
  ) {
    throw new Error("Zoom did not confirm the requested meeting. Check Zoom before running again.");
  }
  return {
    calendarEventId: event.eventId,
    zoomMeetingId: String(meeting.id),
    ...(meeting.joinUrl ? { joinUrl: meeting.joinUrl } : {}),
  };
}

const { statusCode, body } = $input.first().json;
if (statusCode !== 201) throw new Error("Zoom did not confirm creation.");
const event = $("Prepare the next Zoom meeting").item.json;
return [
  {
    json: confirmMeeting(event, {
      id: body.id,
      topic: body.topic,
      startTime: body.start_time,
      duration: body.duration,
      joinUrl: body.join_url,
    }),
  },
];
